package com.tanerinal.education.mapper;import com.tanerinal.education.domain.OutboxEvent;import java.util.List;import org.apache.ibatis.annotations.*;public interface OutboxMapper{@Insert("INSERT INTO payment_outbox(event_id,aggregate_type,aggregate_id,event_type,topic,payload) VALUES(#{eventId},#{aggregateType},#{aggregateId},#{eventType},#{topic},CAST(#{payload} AS JSON))")void insert(@Param("eventId")String eventId,@Param("aggregateType")String aggregateType,@Param("aggregateId")String aggregateId,@Param("eventType")String eventType,@Param("topic")String topic,@Param("payload")String payload);@Select("SELECT * FROM payment_outbox WHERE status IN ('NEW','RETRY') AND next_attempt_at<=CURRENT_TIMESTAMP ORDER BY id LIMIT 50")List<OutboxEvent> pending();@Update("UPDATE payment_outbox SET status='PUBLISHED',published_at=CURRENT_TIMESTAMP,attempts=attempts+1 WHERE id=#{id} AND status<>'PUBLISHED'")int published(Long id);@Update("UPDATE payment_outbox SET status='RETRY',attempts=attempts+1,next_attempt_at=DATE_ADD(CURRENT_TIMESTAMP,INTERVAL 5 SECOND) WHERE id=#{id}")void retry(Long id);@Insert("INSERT IGNORE INTO kafka_consumed_event(consumer_group,event_id,topic) VALUES(#{group},#{eventId},#{topic})")int consume(@Param("group")String group,@Param("eventId")String eventId,@Param("topic")String topic);}
